class TodoWidget extends StatelessWidget {
  const TodoWidget({super.key});
  @override
  Widget build(BuildContext context) {
    return QueryBuilder<List<Todo>, Exception>(
      options: QueryOptions(
        queryKey: QueryKey(['todos']),
        queryFn: TodosAPI.getInstance().getAll,
      ),
      builder: (context, todos) {
        if (todos.isLoading) return const Center(child: CircularProgressIndicator());
        if (todos.isError) return Center(child: Text(todos.error!.toString()));
        return ListView.builder(
          itemCount: todos.data!.length,
          itemBuilder: (context, index) => ListTile(title: Text(todos.data![index].text)),
        );
      },
    );
  }
}
